<template>
    <div>
        <v-card class="mb-4">
            <v-card-title class="d-flex flex-wrap align-center ga-3"><span>CAPEX</span><v-spacer/><v-btn color="primary" prepend-icon="las la-plus" @click="openCreate">新增项目</v-btn></v-card-title>
            <v-card-subtitle>资本性支出、分期偿还进度与未来现金流承诺</v-card-subtitle>
            <v-card-text>
                <v-alert v-if="message" :type="messageType" variant="tonal" class="mb-4" closable @click:close="message=''">{{ message }}</v-alert>
                <v-row>
                    <v-col cols="12" sm="6" lg="3"><v-card variant="tonal"><v-card-text><div class="text-medium-emphasis">项目总额</div><div class="text-h5">{{ money(summary.total) }}</div><div class="text-caption">{{ purchases.length }} 个项目</div></v-card-text></v-card></v-col>
                    <v-col cols="12" sm="6" lg="3"><v-card variant="tonal" color="success"><v-card-text><div class="text-medium-emphasis">已完成本金</div><div class="text-h5">{{ money(summary.paid) }}</div><div class="text-caption">{{ summary.completedCount }} 期已完成，其中 {{ summary.rawPaidCount }} 期有核销记录</div></v-card-text></v-card></v-col>
                    <v-col cols="12" sm="6" lg="3"><v-card variant="tonal" color="primary"><v-card-text><div class="text-medium-emphasis">剩余本金</div><div class="text-h5">{{ money(summary.remaining) }}</div><div class="text-caption">{{ summary.remainingCount }} 期待偿还</div></v-card-text></v-card></v-col>
                    <v-col cols="12" sm="6" lg="3"><v-card variant="tonal" :color="summary.overdueCount ? 'warning' : 'info'"><v-card-text><div class="text-medium-emphasis">本月计划</div><div class="text-h5">{{ money(summary.thisMonth) }}</div><div class="text-caption">{{ summary.overdueCount ? `${summary.overdueCount} 期逾期待处理` : '没有逾期计划' }}</div></v-card-text></v-card></v-col>
                </v-row>
            </v-card-text>
        </v-card>

        <v-row class="mb-1">
            <v-col cols="12" lg="8"><v-card height="100%">
                <v-card-title class="d-flex align-center"><span>项目进度</span><v-spacer/><v-text-field v-model="projectSearch" density="compact" hide-details clearable prepend-inner-icon="las la-search" placeholder="搜索项目" style="max-width:240px"/></v-card-title>
                <v-card-text v-if="!filteredProjectRows.length" class="text-center py-10 text-medium-emphasis">暂无 CAPEX 项目</v-card-text>
                <v-expansion-panels v-else variant="accordion" class="px-4 pb-4"><v-expansion-panel v-for="row in filteredProjectRows" :key="row.purchase.id">
                    <v-expansion-panel-title><div class="project-title"><div class="d-flex align-center ga-2"><span class="font-weight-medium">{{ row.purchase.item_name }}</span><v-chip size="x-small" :color="row.remaining === 0 ? 'success' : 'primary'">{{ row.remaining === 0 ? '已结清' : '进行中' }}</v-chip></div><div class="text-caption text-medium-emphasis">{{ row.completedCount }}/{{ row.purchase.installment_count }} 期已完成 · {{ row.nextDue ? `待处理第 ${row.nextDue.installment_no} 期（${row.nextDue.due_date}）` : '全部分期已完成' }}<span v-if="row.overdueCount" class="text-warning"> · {{ row.overdueCount }} 期逾期待处理</span></div></div><div class="project-progress"><div class="d-flex justify-space-between text-caption mb-1"><span>已完成 {{ money(row.paid) }}</span><span>剩余 {{ money(row.remaining) }}</span></div><v-progress-linear :model-value="row.progress" height="8" rounded color="primary"/></div></v-expansion-panel-title>
                    <v-expansion-panel-text><v-alert v-if="row.inferredCount" type="info" variant="tonal" density="compact" class="mb-3">已根据最新核销到第 {{ row.latestObservedNo }} 期，认定此前 {{ row.inferredCount }} 期为系统启用前已完成；这些期次不计入剩余本金。</v-alert><v-row class="mb-2"><v-col cols="6" md="3"><div class="text-caption text-medium-emphasis">购买日期</div>{{ row.purchase.purchase_date }}</v-col><v-col cols="6" md="3"><div class="text-caption text-medium-emphasis">项目总额</div>{{ money(row.purchase.total_amount_minor) }}</v-col><v-col cols="6" md="3"><div class="text-caption text-medium-emphasis">分期本金</div>{{ money(row.financed) }}</v-col><v-col cols="6" md="3"><div class="text-caption text-medium-emphasis">购买时首付款</div>{{ money(row.purchase.down_payment_minor) }}</v-col></v-row><v-table density="compact"><thead><tr><th>期次</th><th>到期日</th><th class="text-end">计划本金</th><th class="text-end">实际核销</th><th>状态</th></tr></thead><tbody><tr v-for="item in row.installments" :key="item.id" :class="installmentTone(item)"><td>第 {{ item.installment_no }}/{{ row.purchase.installment_count }} 期</td><td>{{ item.due_date }}</td><td class="text-end">{{ money(item.principal_minor) }}</td><td class="text-end">{{ money(item.actual_paid_minor) }}</td><td><v-chip size="x-small" :color="installmentColor(item)">{{ installmentLabel(item) }}</v-chip></td></tr></tbody></v-table></v-expansion-panel-text>
                </v-expansion-panel></v-expansion-panels>
            </v-card></v-col>
            <v-col cols="12" lg="4"><v-card height="100%"><v-card-title>未来预算容量</v-card-title><v-card-subtitle>工资绩效预测 − 日常支出均值 − 未付 CAPEX</v-card-subtitle><v-card-text><div v-for="item in capacity.slice(0,6)" :key="item.month" class="capacity-row"><div><div class="font-weight-medium">{{ item.month }}</div><div class="text-caption text-medium-emphasis">已承诺 {{ money(item.committed_minor) }}</div></div><div class="text-end"><div :class="item.available_minor >= 0 ? 'text-success' : 'text-warning'">{{ money(item.available_minor) }}</div><div class="text-caption">可用</div></div></div><v-alert v-if="capacity.some(item => item.available_minor < 0)" type="warning" variant="tonal" density="compact" class="mt-4">未来月份可用预算为负，新增 CAPEX 前请检查现金流。</v-alert></v-card-text></v-card></v-col>
        </v-row>

        <v-card><v-card-title class="d-flex flex-wrap align-center ga-3"><span>付款日程</span><v-spacer/><v-btn-toggle v-model="scheduleView" mandatory density="compact" color="primary"><v-btn value="attention">待处理</v-btn><v-btn value="upcoming">未来</v-btn><v-btn value="all">全部</v-btn></v-btn-toggle></v-card-title><v-card-subtitle>{{ scheduleSubtitle }}</v-card-subtitle><v-table density="comfortable"><thead><tr><th>到期日</th><th>项目</th><th>期次</th><th class="text-end">本金</th><th class="text-end">实际核销</th><th>状态</th></tr></thead><tbody><tr v-if="!visibleSchedule.length"><td colspan="6" class="text-center py-8 text-medium-emphasis">当前视图没有分期计划</td></tr><tr v-for="item in visibleSchedule" :key="item.id" :class="installmentTone(item)"><td>{{ item.due_date }}</td><td>{{ purchaseName(item.purchase_id) }}</td><td>第 {{ item.installment_no }}/{{ purchaseById(item.purchase_id)?.installment_count }} 期</td><td class="text-end">{{ money(item.principal_minor) }}</td><td class="text-end">{{ money(item.actual_paid_minor) }}</td><td><v-chip size="small" :color="installmentColor(item)">{{ installmentLabel(item) }}</v-chip></td></tr></tbody></v-table></v-card>

        <v-dialog v-model="createDialog" max-width="820"><v-card><v-card-title>新增 CAPEX 项目</v-card-title><v-card-subtitle>金额按元填写；购买时首付款不会被重复计入分期本金</v-card-subtitle><v-card-text><v-alert v-if="createMessage" type="error" variant="tonal" class="mb-4">{{ createMessage }}</v-alert><v-row><v-col cols="12" md="6"><v-text-field v-model="form.item_name" label="项目名称"/></v-col><v-col cols="12" md="3"><v-text-field v-model="form.purchase_date" label="购买日期"/></v-col><v-col cols="12" md="3"><v-text-field v-model.number="form.financed_yuan" type="number" min="0.01" step="0.01" label="分期本金总额（元）"/></v-col><v-col cols="12" md="3"><v-text-field v-model.number="form.down_payment_yuan" type="number" min="0" step="0.01" label="购买时首付款（元）"/></v-col><v-col cols="12" md="3"><v-text-field v-model.number="form.installment_count" type="number" min="1" step="1" label="分期数"/></v-col><v-col cols="12" md="3"><v-text-field v-model="form.first_due_date" label="首期日期"/></v-col><v-col cols="12" md="3"><v-text-field v-model.number="form.interest_fee_yuan" type="number" min="0" step="0.01" label="总利息/手续费（元）"/></v-col><v-col cols="12"><v-text-field v-model="form.note" label="备注（可选）"/></v-col></v-row><v-alert type="info" variant="tonal">项目总额 {{ money(createTotalYuan * 100) }}；预计每期本金约 {{ money(estimatedInstallmentMinor) }}。利息/手续费作为 OPEX，不计入 CAPEX 本金。</v-alert></v-card-text><v-card-actions><v-spacer/><v-btn @click="createDialog=false">取消</v-btn><v-btn color="primary" :loading="saving" :disabled="!createValid" @click="add">新增并生成计划</v-btn></v-card-actions></v-card></v-dialog>
    </div>
</template>

<script setup lang="ts">
import axios from 'axios';
import { computed, onMounted, ref } from 'vue';
const purchases=ref<any[]>([]), installments=ref<any[]>([]), capacity=ref<any[]>([]); const saving=ref(false), message=ref(''), createMessage=ref(''); const messageType=ref<'success'|'error'>('success'); const createDialog=ref(false), projectSearch=ref(''), scheduleView=ref<'attention'|'upcoming'|'all'>('attention'); const today=new Date().toISOString().slice(0,10), currentMonth=today.slice(0,7);
const blankForm=()=>({item_name:'',purchase_date:today,financed_yuan:0,down_payment_yuan:0,installment_count:1,first_due_date:today,interest_fee_yuan:0,financing_type:'INSTALLMENT',currency:'CNY',note:''}); const form=ref(blankForm());
const money=(minor:number)=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(Number(minor||0)/100); const purchaseById=(id:number)=>purchases.value.find(item=>Number(item.id)===Number(id)); const purchaseName=(id:number)=>purchaseById(id)?.item_name||`项目 #${id}`; const isPaid=(item:any)=>item.status==='PAID';
const projectRows=computed(()=>purchases.value.map(purchase=>{const rows=installments.value.filter(x=>Number(x.purchase_id)===Number(purchase.id)).sort((a,b)=>Number(a.installment_no)-Number(b.installment_no)),latestObservedNo=rows.reduce((max,x)=>Number(x.actual_paid_minor||0)>0?Math.max(max,Number(x.installment_no)):max,0),latestPaidNo=rows.reduce((max,x)=>isPaid(x)?Math.max(max,Number(x.installment_no)):max,0),completedThrough=Math.max(latestPaidNo,latestObservedNo-1),inferredIds=new Set(rows.filter(x=>Number(x.installment_no)<=completedThrough&&!isPaid(x)).map(x=>Number(x.id))),effectivePaid=(x:any)=>Number(x.installment_no)<=completedThrough?Number(x.principal_minor||0):Math.min(Number(x.principal_minor||0),Number(x.actual_paid_minor||0)),remainingInstallments=rows.filter(x=>effectivePaid(x)<Number(x.principal_minor||0)),paid=rows.reduce((s,x)=>s+effectivePaid(x),0),financed=Number(purchase.total_amount_minor||0)-Number(purchase.down_payment_minor||0),remaining=remainingInstallments.reduce((s,x)=>s+Number(x.principal_minor||0)-effectivePaid(x),0);return{purchase,installments:rows,financed,paid,remaining,remainingInstallments,completedCount:rows.length-remainingInstallments.length,rawPaidCount:rows.filter(isPaid).length,progress:financed>0?Math.min(100,paid/financed*100):0,nextDue:remainingInstallments[0],overdueCount:remainingInstallments.filter(x=>String(x.due_date)<today).length,inferredCount:inferredIds.size,inferredIds,latestObservedNo}}).sort((a,b)=>b.remaining-a.remaining));
const projectRowById=computed(()=>new Map(projectRows.value.map(row=>[Number(row.purchase.id),row]))); const isInferredComplete=(item:any)=>projectRowById.value.get(Number(item.purchase_id))?.inferredIds.has(Number(item.id))||false; const isEffectivelyComplete=(item:any)=>isPaid(item)||isInferredComplete(item); const isOverdue=(item:any)=>!isEffectivelyComplete(item)&&String(item.due_date)<today; const remainingInstallments=computed(()=>projectRows.value.flatMap(row=>row.remainingInstallments));
const summary=computed(()=>{const rows=projectRows.value,total=purchases.value.reduce((s,x)=>s+Number(x.total_amount_minor||0),0),remainingRows=remainingInstallments.value;return{total,paid:rows.reduce((s,x)=>s+x.paid,0),remaining:rows.reduce((s,x)=>s+x.remaining,0),completedCount:rows.reduce((s,x)=>s+x.completedCount,0),rawPaidCount:rows.reduce((s,x)=>s+x.rawPaidCount,0),remainingCount:remainingRows.length,thisMonth:remainingRows.filter(x=>String(x.due_date).startsWith(currentMonth)).reduce((s,x)=>s+Number(x.principal_minor||0)-Math.min(Number(x.principal_minor||0),Number(x.actual_paid_minor||0)),0),overdueCount:remainingRows.filter(isOverdue).length}});
const filteredProjectRows=computed(()=>{const q=projectSearch.value.trim().toLowerCase();return q?projectRows.value.filter(row=>String(row.purchase.item_name).toLowerCase().includes(q)):projectRows.value});
const attentionStats=computed(()=>{const monthRows=remainingInstallments.value.filter(x=>String(x.due_date).startsWith(currentMonth)),historyRows=remainingInstallments.value.filter(x=>isOverdue(x)&&!String(x.due_date).startsWith(currentMonth));return{monthRows:monthRows.sort((a,b)=>String(a.due_date).localeCompare(String(b.due_date))),historyRows:historyRows.sort((a,b)=>String(b.due_date).localeCompare(String(a.due_date)))}});
const visibleSchedule=computed(()=>{if(scheduleView.value==='attention')return[...attentionStats.value.monthRows,...attentionStats.value.historyRows.slice(0,10)];let rows=[...installments.value];if(scheduleView.value==='upcoming')rows=remainingInstallments.value.filter(x=>String(x.due_date)>=today);return rows.sort((a,b)=>String(a.due_date).localeCompare(String(b.due_date))).slice(0,scheduleView.value==='all'?200:40)});
const scheduleSubtitle=computed(()=>scheduleView.value==='attention'?`本月 ${attentionStats.value.monthRows.length} 期 · 最近 ${Math.min(10,attentionStats.value.historyRows.length)}/${attentionStats.value.historyRows.length} 期逾期待处理`:scheduleView.value==='upcoming'?'从今天开始的未来付款安排':'全部历史与未来分期'); const installmentLabel=(x:any)=>isPaid(x)?'已核销':isInferredComplete(x)?'历史已完成':Number(x.actual_paid_minor||0)>0?'部分核销':isOverdue(x)?'逾期待处理':String(x.due_date).startsWith(currentMonth)?'本月应付':'计划中'; const installmentColor=(x:any)=>isPaid(x)?'success':isInferredComplete(x)?'info':isOverdue(x)?'warning':String(x.due_date).startsWith(currentMonth)?'primary':'default'; const installmentTone=(x:any)=>isOverdue(x)?'overdue-row':'';
const createTotalYuan=computed(()=>Number(form.value.financed_yuan||0)+Number(form.value.down_payment_yuan||0)); const estimatedInstallmentMinor=computed(()=>Number(form.value.installment_count)>0?Math.round(Number(form.value.financed_yuan||0)*100/Number(form.value.installment_count)):0); const createValid=computed(()=>Boolean(form.value.item_name.trim())&&/^\d{4}-\d{2}-\d{2}$/.test(form.value.purchase_date)&&/^\d{4}-\d{2}-\d{2}$/.test(form.value.first_due_date)&&Number(form.value.financed_yuan)>0&&Number(form.value.down_payment_yuan)>=0&&Number(form.value.interest_fee_yuan)>=0&&Number.isInteger(Number(form.value.installment_count))&&Number(form.value.installment_count)>=1);
function openCreate(){form.value=blankForm();createMessage.value='';createDialog.value=true} async function load(){const[list,cap]=await Promise.all([axios.get('v1/hengcai/capex/list.json'),axios.get('v1/hengcai/capex/capacity.json')]);purchases.value=list.data.result?.purchases||[];installments.value=list.data.result?.installments||[];capacity.value=cap.data.result||[]}
async function add(){if(!createValid.value)return;saving.value=true;createMessage.value='';try{await axios.post('v1/hengcai/capex/add.json',{item_name:form.value.item_name.trim(),purchase_date:form.value.purchase_date,total_amount_minor:Math.round(createTotalYuan.value*100),down_payment_minor:Math.round(Number(form.value.down_payment_yuan)*100),installment_count:Number(form.value.installment_count),first_due_date:form.value.first_due_date,financing_type:form.value.financing_type,interest_fee_total_minor:Math.round(Number(form.value.interest_fee_yuan)*100),currency:form.value.currency,note:form.value.note.trim()});await load();createDialog.value=false;messageType.value='success';message.value='CAPEX 项目已新增并生成分期计划'}catch(ex:any){createMessage.value=ex?.response?.data?.errorMessage||'CAPEX 保存失败'}finally{saving.value=false}}
onMounted(()=>load().catch(()=>{messageType.value='error';message.value='CAPEX 数据加载失败'}));
</script>

<style scoped>
.project-title{width:34%;min-width:220px}.project-progress{width:44%;min-width:260px;margin-left:auto;margin-right:24px}.capacity-row{display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid rgba(var(--v-border-color),var(--v-border-opacity))}.capacity-row:last-child{border-bottom:0}.overdue-row{background:rgba(var(--v-theme-warning),.07)}@media(max-width:700px){.project-title{width:100%}.project-progress{display:none}}
</style>
